// A helper function for converting inline HTML tags to their equivalents in Markdown syntax
std::string toMarkdown(const std::string& tag) {
    static std::unordered_map<std::string, std::string> translations = {   // a cache to avoid redundant lookups
        {"b", "**"},     {"strong", "**"},     {"em", "*"},       {"emphasis", "*"},
        {"i", "_"},       {"italic", "_"},      {"code", "`"},     {"code", "\\`"},
        {"a", "[["}
    };
    auto it = translations.find(tag);
    return it != translations.end() ? it->second : tag;
}

// The main function to convert Markdown to HTML
std::string markdownToHtml(std::string& mdText) {
    // Create regular expressions for parsing different parts of Markdown syntax
    std::regex reLink("[\\[\\]]*?\\(([^)]*)\\)");         // links
    std::regex reInlineTag("(\\b" + rxAnyChar + "+)\\1");  // inline tags (bold, italic, code, etc.)
    std::regex reBlockTag("^(" + rxAnyChar + "++)\\1$");   // block tags (paragraph, heading, list, table, etc.)

    std::string htmlText;
    bool inCode = false;  // keep track of whether we're inside a code span

    // Iterate over characters in the input Markdown text
    std::size_t pos = 0;
    while ((pos = mdText.find_first_not_of(" \r\n", pos)) != std::string::npos) {
        std::size_t endPos = mdText.find_next_not_of(" \r\n", pos + 1);
        std::string chunk(mdText.substr(pos, endPos - pos));

        // Parse text chunks based on their syntax
        if (rxLink.match(chunk)) {
            std::smatch match;
            std::string linkContent;
            if (std::regex_search(chunk, match, reLink)) {
                linkContent = match[1];
                chunk = "[ " + linkContent + " ](" + linkContent + ")";
            } else {
                std::cerr << "Badly formed link in \"" << chunk << "\". Ignoring.\n";
            }
        } else if (reInlineTag.search(chunk)) {
            std::string tagName;
            if (std::regex_extract(chunk, tagName, reInlineTag)) {
                chunk = toMarkdown(tagName);
            }
        } else if (reBlockTag.match(chunk)) {
            htmlText += "<" + chunk + ">\n";

            // Special handling for paragraphs (to insert line breaks where necessary)
            std::string::size_type paraEnd = endPos;
            while (paraEnd > pos && mdText[paraEnd - 1] != '\n') {
                --paraEnd;
            }
            htmlText += mdText.substr(pos, paraEnd - pos) + "\n";

            pos = endPos;
        } else {
            // Check for code spans
            if (chunk.front() == '`' && (!inCode) || (chunk.back() == '`' && inCode)) {
                inCode ^= true;
                chunk.erase(chunk.begin(), chunk.begin() + (inCode ? 1 : 0));
                chunk.erase(chunk.end() - (inCode ? 1 : 0), chunk.end());

                // Insert escaped backslashes before literal backward slashes within a code span
                std::replace(chunk.begin(), chunk.end(), '\\', inCode ? '\\' : '');
            }

            htmlText += toHtmlEscaped(chunk);  // escape any special characters in plain text
        }

        pos = endPos;
    }

    htmlText += "</" + reBlockTag.sub_pattern(1) + ">";          // close the final block tag

    return htmlText;
}

// Helper function to encode special characters as named HTML entities
std::string toHtmlEscaped(const std::string& str) {
    static const std::unordered_map<char, std::string> htmlEntities = {
        {'&', "&amp;"}, {'>', "&gt;"}, {'<', "&lt;"}, {'"', "&quot;"}, {'\'', "&#39;}"}, {'"', "&apos;"}, {' ', "&nbsp;"}
    };
    std::string result;
    for (char ch : str) {
        auto it = htmlEntities.find(ch);
        result += it != htmlEntities.end() ? it->second : std::string{1, ch};
    }
    return result;
}

int main() {
    std::string mdText = R"(
# Heading 1
This is some **important** text, *with* emphases and `inline code`. And a [link][id].

[id]: https://example.com/ "Some link title"

## Heading 2

List:
- Item 1
