JavaScript:

```javascript
// Get references to necessary elements in DOM
const openChat = document.getElementById("open-chat");
const chatModal = document.getElementById("chat-modal");
const closeButton = chatModal.querySelector(".close");
const messagesList = chatModal.querySelector(".messages");

// Define initial messages array with 2 user and 2 bot messages
const chatHistory = [
  { role: "user", message: "Hello, how can I help you today?" },
  { role: "assistant", message: "I am available to assist you anytime." },
  { role: "user", message: "That sounds great. Can you provide me more details on the pricing plans?" },
  { role: "assistant", message: "Sure, our plans vary based on features. Which one are you most interested in?" }
];

// Open/Close modal functionality
function toggleChat() {
  chatModal.classList.toggle("show");
}

openChat.addEventListener("click", toggleChat);
closeButton.addEventListener("click", toggleChat);

// Dynamically populate messages list when modal opens/reloads
function renderChatMessages() {
  const messagesElement = document.createElement("li");
  messagesList.innerHTML = ""; // Clear previous messages first

  chatHistory.forEach(message => {
    const newMessage = document.createElement("div");
    newMessage.classList.add(`message`, `${message.role}`);
    newMessage.innerText = message.message;

    messagesElement.appendChild(newMessage);
  });

  messagesList.appendChild(messagesElement);
}

renderChatMessages(); // Render initial chat history

// Example event listener to simulate adding new user message to chat history
document.getElementById('add-message').addEventListener('click', () => {
  const newUserMessageInput = prompt("Enter your message:");
   if (newUserMessageInput) {
     chatHistory.push({ role: 'user', message: newUserMessageInput });
     renderChatMessages();
   }
});
```

This example will render the defined initial chat history with 2 messages from each user (human and AI). You can modify the `chatHistory` array to update the messages based on your specific requirements.

Also, note how the `renderChatMessages()` function clears the messages list before appending the newly rendered messages. This ensures that there aren't duplicates or inconsistent styling issues.

