#include <iostream> // for std::cout, std::cin, etc.
#include <fstream> // for std::ifstream (file input stream)
#include <string> // for std::string
#include <vector> // for std::vector

int main() {
    std::string filename, search_word;
    int word_count = 0;

    // Ask user for file name and search word
    std::cout << "Enter filename: ";
    std::getline(std::cin, filename);
    std::cout << "Enter word to search for: ";
    std::getline(std::cin, search_word);

    // Open file for reading
    std::ifstream file(filename);
    if (!file.is_open()) { // Check if file could be opened
        std::cerr << "Error: Failed to open file" << std::endl;
        return 1;
    }

    // Read each line of file
    std::string line;
    while (std::getline(file, line)) {
        // Split line into words
        std::vector<std::string> tokens;
        size_t start_pos = 0;
        size_t pos = 0;

        while ((pos = line.find(" ", start_pos)) != std::string::npos) {
            tokens.emplace_back(line.substr(start_pos, pos - start_pos));
            start_pos = pos + 1; // Move beyond current space character
        }

        tokens.emplace_back(line.substr(start_pos, line.length() - start_pos));

        // Count occurrences of search word in line's words
        for (const auto& token : tokens) {
            if (token == search_word) ++word_count;
        }
    }

    // Close file and print result
    file.close();
    std::cout << "The word \"" << search_word << "\" appears " << word_count << " times in file \"" << filename << "\".\n";

    return 0;
}
```

Note that this code assumes the search word does not contain spaces or any other characters treated as word separators (in this case, only whitespace is used). Also note that it doesn't handle cases where the search word appears broken across lines (because each line is processed independently). Finally, this implementation uses `std::cerr` instead of plain `std::cout` for error messages, so they show up on standard error rather than mixed with normal output.
